inline float compensated_ggx_single_scatter_albedo(const float roughness, const float NoV) {
    float x = clamp(roughness, 0.0f, 1.0f) * 48.0f;
    float y = sqrt(clamp(NoV, 0.0f, 1.0f)) * 48.0f;
    uint i = min(static_cast<uint>(x), 47u);
    uint j = min(static_cast<uint>(y), 47u);
    float tx = x - float(i);
    float ty = y - float(j);
    uint k = i * 49u + j;
    float a = mix(kGgxSingleScatterAlbedo[k], kGgxSingleScatterAlbedo[k + 1u], ty);
    float b = mix(kGgxSingleScatterAlbedo[k + 49u], kGgxSingleScatterAlbedo[k + 50u], ty);
    return mix(a, b, tx);
}

// Fdez-Aguera scale: (FssEss + Fms*Ems)/FssEss = 1/(1 - Favg*Ems).
// Ess integrates this renderer's separable-Smith GGX with F=1, independently
// of Fresnel transmission. White roughness-1 needs 1/Ess ~= 3.259, below 4.
inline float3 specular_energy_compensation(const float3 f0,
                                           const float roughness,
                                           const float NoV) {
    float Ess = clamp(compensated_ggx_single_scatter_albedo(roughness, NoV), 1.0e-4f, 1.0f);
    float Ems = 1.0f - Ess;
    float3 Favg = f0 + (float3(1.0f) - f0) * (1.0f / 21.0f);
    return clamp(float3(1.0f) / max(float3(1.0f) - Ems * Favg, float3(1.0e-4f)),
                 float3(1.0f), float3(4.0f));
}
